**The bug:** The condition `decoded.exp < Date.now() / 1000` uses strict less-than, so a token where `exp === floor(now)` passes the check — it's neither less than nor... wait, it *is* less than... let me re-read.

Actually: `exp < now` means "expired tokens are those where exp is strictly less than now." A token expiring *exactly* at the current second has `exp === now`, which fails the `<` check and is **incorrectly accepted**. The fix is `<=`.

But there's a deeper issue: `jwt.verify()` **already validates expiration** via the `exp` claim — the manual check is redundant and is the source of the bug. Removing it entirely is cleaner. Here's the corrected version with proper error handling:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  if (!process.env.JWT_SECRET) {
    return res.status(500).json({ error: 'Server misconfiguration' });
  }

  try {
    // jwt.verify already enforces exp — no manual time check needed
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    if (err.name === 'NotBeforeError') {
      return res.status(401).json({ error: 'Token not yet valid' });
    }
    res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Summary of changes:**

| Issue | Before | After |
|---|---|---|
| Off-by-one on expiry | Manual `exp < now` (misses `===`) | Removed — `jwt.verify` handles this correctly with `<=` semantics |
| Error handling | All errors → same `'Invalid token'` | Distinguishes `TokenExpiredError`, `JsonWebTokenError`, `NotBeforeError` |
| Missing secret | Silent failure / crashes | Returns 500 with clear message |
